(function(){
'use strict';
const L=Lesson,M=Model,R=LearningChecks,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,lang='en',device='auto',notice='',noticeType='',extension=null,runner=null,frame=null,frameListener=null,timeout=null,busy=false,pdfFile=null,bundleFile=null,saveTimer=null,dbPromise=null,grid=true,legacy=null,reportVisible=false;
const mapImage=new Image();mapImage.src='assets/school-map.png';mapImage.onload=()=>paint();
const memoryShots=new Map();
const both=p=>p?esc(p.en)+(lang==='zh'&&p.zh?'<span class="zh" lang="zh-Hans">'+esc(p.zh)+'</span>':''):'';
const t=(en,zh)=>both({en,zh});
const text=(en,zh)=>lang==='zh'?en+' / '+zh:en;
const B=(en,zh,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${t(en,zh)}</button>`;
function db(){if(!dbPromise)dbPromise=new Promise((res,rej)=>{const r=indexedDB.open('y7-w2-turtle-evidence-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('shots');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});return dbPromise;}
async function putShot(id,shot){const key=M.key(state.name,state.klass)+':'+id;memoryShots.set(key,shot);try{const d=await db();await new Promise((res,rej)=>{const tx=d.transaction('shots','readwrite');tx.objectStore('shots').put(shot,key);tx.oncomplete=res;tx.onerror=()=>rej(tx.error);});}catch(e){showNotice(text('Drawing storage is unavailable. Keep this page open and export before leaving.','图形存储暂不可用。请保持页面打开，并在离开前导出。'),'error');}}
async function getShot(id){const key=M.key(state.name,state.klass)+':'+id;if(memoryShots.has(key))return memoryShots.get(key);try{const d=await db();return await new Promise((res,rej)=>{const r=d.transaction('shots').objectStore('shots').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}catch{return null;}}
function log(action,value=''){if(!state)return;if(/^(Reflection|Selected answer|Checked answer|Chose destination|Selected command|Next learning|Code draft|Ran Python|Stopped program|Reset workspace|Undo code|Inserted|Completed card|Requested teacher help|Started extension|extension-|Language support)/.test(action)){pdfFile=null;bundleFile=null;}state.events.push({at:new Date().toISOString(),card:current().id,action,value:String(value).slice(0,2000)});save();}
function save(immediate=false){if(!state)return;clearTimeout(saveTimer);const work=()=>{try{state.updated=new Date().toISOString();localStorage.setItem(M.key(state.name,state.klass),JSON.stringify(state));if($('saved'))$('saved').textContent=text('Saved on this device','已保存在此设备');}catch(e){if($('saved'))$('saved').textContent=text('Not saved — make a backup','未保存：请导出备份');showNotice(text('Browser storage is full or blocked. Keep this page open. Use Device help → Download backup.','浏览器存储已满或被阻止。请保持页面打开，点击设备帮助 → 导出备份。'),'error');}};if(immediate)work();else saveTimer=setTimeout(work,200);}
function current(){if(extension){const e=L.extensions.find(e=>e.id===extension);return {id:e.id,stage:4,title:e.title,read:e.read,action:L.pair('EDIT the code, RUN, then compare your drawing with the challenge.','修改代码、运行，然后将图形与任务要求比较。'),kind:'code',workspace:e.id,initial:e.initial,run:true};}return L.cards[state?state.current:0];}
function work(){return M.workspace(state,current());}
function sync(){const box=$('code');if(box&&state&&current().workspace){const w=work();if(w.code!==box.value){w.code=box.value;pdfFile=null;bundleFile=null;save(true);}}}
function header(){return `<header class="learning"><div class="brand-row"><strong>Year 7 · Week 2 Practical</strong><span>${state?esc(state.name)+(state.klass?' · '+esc(state.klass):''):text('My first Python route','我的第一个 Python 路线程序')}</span><div class="tools"><label class="sr-only" for="language">${text('Language support','语言帮助')}</label><select id="language" aria-label="Language support"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="zh" ${lang==='zh'?'selected':''}>English + 中文</option></select>${B('Device help','设备帮助','device-help')}${state?B('Words','词语','words'):''}</div></div><div class="wagba"><strong>WAGBA</strong><p>${both(L.goals.wagba)}</p></div><div class="keywords"><strong>${text('Keywords','关键词')}</strong>${L.terms.map((v,i)=>`<button class="word" data-word="${i}">${esc(v[0])}${lang==='zh'?' · '+esc(v[1]):''}</button>`).join('')}</div><div class="ksu"><p><strong>${text('Knowledge','知识')}</strong>${both(L.goals.knowledge)}</p><p><strong>${text('Skills','技能')}</strong>${both(L.goals.skills)}</p><p><strong>${text('Understanding','理解')}</strong>${both(L.goals.understanding)}</p></div></header>`;}
function landing(){ $('app').innerHTML=header()+`<main class="entry"><section><span class="eyebrow">${text('A small step into Python','迈出学习 Python 的一小步')}</span><h1>${t('Draw a route. One command at a time.','画一条路线，一次学一条指令。')}</h1><p>${t('First, try a few short Turtle commands. Then use them to help a new student find a room on our practice map.','先尝试几条简短的 Turtle 指令，再用它们帮助新同学在练习地图上找到一个房间。')}</p><img class="map-hero" src="assets/school-map.svg" alt="Practice school map: Main Entrance, Reception, Library and CS Room C1"><p class="entry-note">${t('No installation. No folders to set up. We will guide you through saving at the end.','不用安装软件，不用先创建文件夹。课程结束时会指导你保存文件。')}</p></section><form id="entry-form" novalidate><h2>${t('Ready to begin?','准备开始了吗？')}</h2><label for="name">${t('Your full name','你的姓名')}</label><input id="name" maxlength="80" autocomplete="name" required><label for="klass">${t('Your class','你的班级')}</label><input id="klass" maxlength="30" placeholder="7T" required><label for="entry-device">${t('Your device','你的设备')}</label><select id="entry-device"><option value="auto">${text('Not sure / automatic','不确定 / 自动')}</option><option value="ipad">iPad / iPhone</option><option value="computer">Mac / Windows / Chromebook</option><option value="android">Android tablet</option></select><p id="entry-error" class="notice error hidden" role="alert"></p><button class="primary" type="submit">${t('Start or resume','开始或继续')}</button><p class="entry-note">${t('Work stays in this browser on this device. Use the same name and class to resume. On a shared device, tell your teacher before opening someone else’s work.','学习记录保存在此设备的这个浏览器中。使用相同姓名和班级即可继续。在共用设备上，请勿打开别人的学习记录。')}</p></form></main>`;}
function quiz(c){if(!c.question)return '';const a=state.answers[c.id]||{},q=c.question;let feedback='';if(a.checked){feedback=c.choiceOnly?t('Your choice is saved.','已保存你的选择。'):a.value===q.correct?t('That matches the example. You can continue.','与例子一致，可以继续。'):t('Look again at the example. The helpful answer is: '+q.choices[q.correct].en+'. You may try again or continue with this help.','再看看例子。正确的思路是：'+q.choices[q.correct].zh+'。你可以再试一次，或参考提示继续。');}
return `<fieldset class="question" id="question"><legend>${both(q.prompt)}</legend><div class="choices">${q.choices.map((p,i)=>`<label class="choice"><input type="radio" name="answer" value="${i}" ${a.value===i?'checked':''}><span>${both(p)}</span></label>`).join('')}</div>${B(c.choiceOnly?'Save my choice':'Check my thinking',c.choiceOnly?'保存选择':'检查我的想法','check','check-btn')}${feedback?`<div class="notice ${c.choiceOnly||a.value===q.correct?'success':''}" role="status">${feedback}</div>`:''}</fieldset>`;}
function codeLinesSelect(c){const code=(state.work.route?.code||'').split('\n').filter(l=>l.trim()&&!l.trim().startsWith('#'));return `<label class="form-line">${t('A command I can explain','我能解释的指令')}<select id="explain-line"><option value="">${text('Choose a line','选择一行')}</option>${code.map(l=>`<option ${state.answers[c.id+'Line']===l?'selected':''} value="${esc(l)}">${esc(l)}</option>`).join('')}<option value="I need help reading my code" ${state.answers[c.id+'Line']==='I need help reading my code'?'selected':''}>${text('I need help reading my code','我需要帮助读懂代码')}</option></select></label><p class="muted">${t('Say: “This command moves Turtle to x = ___, y = ___.” Point to its endpoint on the map.','说：“这条指令把 Turtle 移动到 x = ___、y = ___。”然后指出地图上的终点。')}</p>`;}
function runnerUI(c){const w=M.workspace(state,c);return `<div class="workspace"><section><p class="pane-label">${t('Your Python instructions','你的 Python 指令')}</p><div class="editor-box"><div class="editor-meta"><span>Python · t = Turtle</span><span id="cursor">${text('Line','行')} 1</span></div><div class="code-shell"><pre class="lines" id="lines" aria-hidden="true"></pre><div class="code-area"><pre class="syntax" id="syntax" aria-hidden="true"></pre><textarea id="code" class="code-input" aria-label="Python code editor" spellcheck="false" autocorrect="off" autocapitalize="off" autocomplete="off" translate="no">${esc(w.code)}</textarea></div></div><div class="punctuation" aria-label="Python punctuation helpers">${['t.goto(',')',',','-','\n'].map(p=>`<button data-insert="${esc(p)}" aria-label="Insert ${p==='\n'?'new line':esc(p)}">${p==='\n'?'↵':esc(p)}</button>`).join('')}</div></div><div class="editor-tools">${B('Run','运行','run','run',busy?'disabled':'')}${B('Stop','停止','stop','',!busy?'disabled':'')}${B('Undo edit','撤销修改','undo')}${B('Reset this code','重置这段代码','reset-code','small')}</div><div id="console" class="console" role="status">${esc(busy?text('Running Python…','正在运行 Python……'):w.output||text('Ready. Use Run to see your drawing.','准备好了。点击运行，查看图形。'))}</div></section><section><p class="pane-label">${c.map?t('Your route on the map','地图上的路线'):t('Your drawing','你的图形')}</p><div class="canvas-frame"><canvas id="drawing" class="drawing" width="800" height="600" role="img" aria-label="${c.map?'Practice map with Turtle route and labelled x and y axes':'Turtle drawing with labelled x and y axes'}" ${c.map?'tabindex="0"':''}></canvas></div><p class="canvas-caption">${c.map?t('START = (0, -200) · FINISH = '+L.destinations[state.destination].label.en,'起点 = (0, -200) · 终点 = '+L.destinations[state.destination].label.zh):t('Centre = (0, 0). x: left/right. y: down/up.','中心 = (0, 0)。x：左右位置；y：上下位置。')}</p>${c.map&&(c.pick||c.picker)?pointUI(c):''}${c.routeCheck?routeResult():''}</section></div>${c.explain?codeLinesSelect(c):''}`;}
function pointUI(c){const p=state.picked,points=c.pick?[[0,-100]]:state.destination==='reception'?[[0,-100],[-100,-100],[-200,-100]]:[[0,-100],[0,0],[0,100],[state.destination==='library'?-100:100,100],[state.destination==='library'?-200:200,100]];return `<div class="pointbar"><strong>${p?esc(`x = ${p[0]}, y = ${p[1]}`):t('Tap a point on the map','点击地图上的一个点')}</strong><p>${t('Or choose a labelled point below. These buttons also work with a keyboard.','也可以选择下面的坐标按钮，键盘同样可以操作。')}</p><div class="point-options">${points.map(v=>`<button data-point="${v.join(',')}" aria-label="Select point ${v.join(', ')}">(${v.join(', ')})</button>`).join('')}</div>${c.picker?B('Insert this point','插入这个点','insert-point','',p?'':'disabled'):''}</div>`;}
function routeResult(){const w=state.work.route,checks=L.checkRoute(w?.draws||[],state.destination);return `<div class="check-list">${[['start','Starts at entrance','从正门开始'],['finish','Reaches chosen place','到达目的地'],['safe','Follows corridors','沿走廊前进'],['continuous','One connected line','路线连续']].map(([k,en,zh])=>`<span>${checks[k]?'✓':'Check:'} ${text(en,zh)}</span>`).join('')}</div><p class="canvas-caption">${t('This checks the drawing, not your explanation. Ask a partner to check too.','这只检查图形，不判断你的解释。同伴也需要一起检查。')}</p>`;}
function content(c){let body='';if(R.mode(c))return R.render(state,R.mode(c),{both,t,text,esc,B});if(c.kind==='mission')return `<div class="mission"><div class="lesson-copy"><div class="reading"><span class="tag">${text('THE STORY','情境')}</span><p>${both(c.read)}</p></div><div class="action"><span class="tag">${text('YOUR FIRST ACTION','第一步')}</span><p>${both(c.action)}</p></div><p>${t('First we learn commands on a plain canvas. Then we use the map. You do not have to visit every room.','先在空白画布上学习指令，再使用地图。不需要经过所有房间。')}</p></div><img src="assets/school-map.svg" alt="Practice map with Main Entrance START, Reception, Library and CS Room C1"></div>`;
body=`<div class="reading"><span class="tag">${text('READ · ONE IDEA','阅读 · 一个概念')}</span><p>${both(c.read)}</p></div><div class="action"><span class="tag">${text('YOUR TURN','轮到你了')}</span><p>${both(c.action)}</p>${c.example?`<pre class="example" translate="no">${esc(c.example)}</pre>`:''}</div>`;
if(c.anatomy)body+=`<p>${t('t = drawing tool · . = joins the name to the command · goto = move to · (80, 0) = position','t = 绘图工具 · 点号 = 连接名称与指令 · goto = 移动到 · (80, 0) = 位置')}</p>`;
if(c.kind==='code')body+=runnerUI(c);
else if(c.kind==='point')body+=`<div class="starter-layout"><div class="canvas-frame"><canvas id="drawing" class="drawing" width="800" height="600" role="img" aria-label="Practice map with x and y coordinates and NEXT point"></canvas></div>${pointUI(c)}</div>`;
else if(c.kind==='destination'){body+=`<div class="starter-layout"><img class="compact-map" src="assets/school-map.svg" alt="Practice map"><fieldset class="question"><legend>${t('My destination','我的目的地')}</legend><div class="choices">${Object.entries(L.destinations).map(([id,d])=>`<label class="choice"><input type="radio" name="destination" value="${id}" ${state.destinationChosen&&state.destination===id?'checked':''}><span>${both(d.label)}<br><code>(${d.point.join(', ')})</code></span></label>`).join('')}</div></fieldset></div>`;}
else if(c.kind==='peer'){body+=codeLinesSelect(c);body+=runnerUI({...c,kind:'code',map:true});}
else if(c.kind==='extension'){body+=`<div class="extension-grid">${L.extensions.map(e=>`<article><h2>${both(e.title)}</h2><p>${both(e.read)}</p>${B('Try this challenge','尝试这个任务','extension:'+e.id,'primary')}<p class="muted">${text('Visits','尝试次数')}: ${state.extensionAttempts.filter(a=>a.id===e.id).length}</p></article>`).join('')}</div>`;}
else if(c.kind==='submit')return body+submission();
if(c.question){if(c.map&&!c.workspace)body+=`<div class="starter-layout"><img class="compact-map" src="assets/school-map.svg" alt="Practice school map showing the start and destinations">${quiz(c)}</div>`;else body+=quiz(c);}
if(c.kind==='code'||c.kind==='peer')body+=`<div class="support-row">${B('Show a hint','显示提示','hint')}${B('I need teacher help','我需要老师帮助','support')}${B(grid?'Hide grid':'Show grid',grid?'隐藏网格':'显示网格','grid')}${c.map?B('See setup code','查看准备代码','setup'):''}</div>`;
return body;}
function lessonNavigation(){const starts=L.cards.map((c,i)=>({c,i})).filter(({c,i})=>i===0||c.stage!==L.cards[i-1].stage||['strategy','plenary1'].includes(c.id));const selected=starts.filter(v=>v.i<=state.current).at(-1).i;return starts.map(({c,i})=>{const label=c.id==='strategy'?L.pair('Types of learning','学习类型'):c.id==='reflect'?L.pair('Learning pitstop','学习加油站'):c.id==='plenary1'?L.pair('Plenary & save','课堂小结与保存'):L.stages[c.stage];return `<option value="${i}" ${selected===i?'selected':''} ${!state.teacher&&i>state.unlocked?'disabled':''}>${text(label.en,label.zh)}</option>`;}).join('');}
function reflectionFooter(c){const m=R.mode(c);if(!m)return '';return R.get(state).pages[m]<3?text('Next check','下一项'):m==='before'?text('Start Learn commands','开始学习指令'):text('Continue to plenary','继续课堂小结');}
function render(){if(!state)return landing();const c=current();const count=L.cards.filter(x=>x.id!=='extension'&&x.id!=='submit').length,done=L.cards.filter(c=>!['extension','submit'].includes(c.id)&&M.completed(state,c)).length;
$('app').innerHTML=header()+`<main class="shell"><div class="stagebar"><label><span class="sr-only">Lesson stage</span><select id="stage-select">${lessonNavigation()}</select></label><div class="progress" aria-label="Lesson progress ${done} of ${count}"><span style="width:${Math.min(100,100*done/count)}%"></span></div><span class="saved" id="saved">${text('Saved on this device','已保存在此设备')}</span></div><article class="card" id="card"><div class="card-head"><div><span class="step-label">${R.mode(c)?text('Learning reflection','学习反思'):c.step?text('Practice '+c.step+' of 10','练习 '+c.step+' / 10'):both(L.stages[c.stage])}</span><h1 tabindex="-1" id="card-title">${both(c.title)}</h1></div>${extension?B('Back to choices','返回选择','extension-back','small'):''}</div><div id="notice" class="notice ${noticeType} ${notice?'':'hidden'}" role="alert">${esc(notice)}</div>${content(c)}</article></main><footer class="foot">${B('Back','返回','back','',!extension&&state.current===0?'disabled':'')}<small>${text('One idea. One try.','一个概念，一次尝试。')}</small>${c.kind==='submit'?B('Change student','更换学生','change-student'):extension?B('Finish this attempt','完成本次尝试','extension-finish','primary'):R.mode(c)?`<button class="primary" data-action="next">${esc(reflectionFooter(c))}</button>`:B(c.id==='extension'?'Continue to Learning pitstop':c.id==='mission'?'Begin starter':'Continue',c.id==='extension'?'继续学习加油站':c.id==='mission'?'开始热身':'继续','next','primary')}</footer>`;
if($('code'))highlight();if($('drawing'))paint();if(reportVisible&&$('review-area'))Report.html(state,getShot,legacy).then(html=>{if($('review-area'))$('review-area').innerHTML=html;});document.documentElement.style.scrollPaddingTop=(document.querySelector('.learning').offsetHeight+12)+'px';save();}
function highlight(){const box=$('code');if(!box)return;const safe=esc(box.value);$('syntax').innerHTML=safe.split('\n').map(line=>line.trim().startsWith('#')?'<span class="comment">'+line+'</span>':line.replace(/\b(goto|penup|pendown|forward|right|left|color|circle)\b/g,'<span class="fn">$1</span>').replace(/(-?\b\d+(?:\.\d+)?)\b/g,'<span class="num">$1</span>')).join('\n')+'\n';$('lines').textContent=box.value.split('\n').map((_,i)=>i+1).join('\n');$('syntax').scrollTop=box.scrollTop;$('syntax').scrollLeft=box.scrollLeft;$('lines').scrollTop=box.scrollTop;const before=box.value.slice(0,box.selectionStart);$('cursor').textContent=text('Line','行')+' '+before.split('\n').length;}
function drawOn(canvas,draws,mapMode,showGrid,target,selected){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,800,600);ctx.fillStyle='white';ctx.fillRect(0,0,800,600);if(mapMode&&mapImage.complete&&mapImage.naturalWidth)ctx.drawImage(mapImage,0,0,800,600);
if(showGrid){ctx.save();ctx.font='18px Arial';ctx.textAlign='center';for(let x=-350;x<=350;x+=50){ctx.beginPath();ctx.strokeStyle=x===0?'#8298b1':'#768aa51c';ctx.lineWidth=x===0?2:1;ctx.moveTo(x+400,75);ctx.lineTo(x+400,550);ctx.stroke();if(x%100===0){ctx.fillStyle='#496c91';ctx.fillText(x,x+400,322);}}for(let y=-200;y<=200;y+=50){ctx.beginPath();ctx.strokeStyle=y===0?'#8298b1':'#768aa51c';ctx.lineWidth=y===0?2:1;ctx.moveTo(45,300-y);ctx.lineTo(755,300-y);ctx.stroke();if(y%100===0&&y!==0){ctx.fillStyle='#496c91';ctx.fillText(y,421,306-y);}}ctx.fillStyle='#315776';ctx.font='bold 22px Arial';ctx.fillText('x →',760,317);ctx.fillText('y ↑',420,93);ctx.restore();}
let last=mapMode?[0,-200]:[0,0];for(const d of draws||[]){if(d.clear){ctx.clearRect(0,0,800,600);drawOn(canvas,[],mapMode,showGrid,target,selected);continue;}if(!d.from)continue;if(d.pen){ctx.beginPath();ctx.moveTo(400+d.from[0],300-d.from[1]);ctx.lineTo(400+d.to[0],300-d.to[1]);ctx.strokeStyle=d.color||'#176bba';ctx.lineWidth=d.width||4;ctx.lineCap='round';ctx.stroke();}last=d.to;}
function dot(p,label,color){ctx.beginPath();ctx.arc(400+p[0],300-p[1],14,0,Math.PI*2);ctx.strokeStyle=color;ctx.lineWidth=3;ctx.stroke();ctx.font='bold 20px Arial';ctx.fillStyle=color;ctx.fillText(label,Math.min(665,415+p[0]),Math.max(89,280-p[1]));}
if(mapMode){dot(L.destinations[state?.destination||'c1'].point,'FINISH','#176548');}if(target)dot(target,'NEXT','#996308');if(selected)dot(selected,'('+selected.join(', ')+')','#935909');ctx.beginPath();ctx.arc(400+last[0],300-last[1],7,0,Math.PI*2);ctx.fillStyle='#172b40';ctx.fill();}
function paint(){if(!$('drawing')||!state)return;const c=current(),w=work();drawOn($('drawing'),w?.draws||[],!!c.map,grid,c.target,state.picked&&c.map?state.picked:null);}
function showNotice(msg,type=''){notice=msg;noticeType=type;const n=$('notice');if(n){n.textContent=msg;n.className='notice '+type;n.classList.toggle('hidden',!msg);}}
function go(index){if(busy){showNotice(text('Stop the program before changing cards.','请先停止程序，再切换卡片。'));return;}sync();state.current=Math.max(0,Math.min(L.cards.length-1,index));extension=null;notice='';log('Opened card',L.cards[state.current].title.en);render();$('card-title').focus({preventScroll:true});$('card').scrollIntoView({block:'start'});}
function reflectionPage(page){const m=R.mode(current());if(!m)return;R.get(state).pages[m]=Math.max(0,Math.min(3,page));notice='';log('Reflection opened check',m+': '+R.get(state).pages[m]);render();$('card-title').focus({preventScroll:true});$('card').scrollIntoView({block:'start'});}
function reflectionError(id){const m=R.mode(current()),i=R.topics.findIndex(v=>v.id===id);reflectionPage(i>=0?i:3);const msg=i>=0?text(m==='before'?'Choose how you feel about this check. “This is new to me” or “Not sure / not checked yet” is OK.':'Choose how you feel about this check. “Drowning — I need help” or “Not attempted yet” is OK.',m==='before'?'请选择你对这一项的感受。“这是新内容”或“不确定／还没检查”都可以。':'请选择你对这一项的感受。“我需要帮助”或“还没有尝试”都可以。'):id==='focus'?text('Choose one topic for your next step.','请选择下一步要练习的一个主题。'):text('Choose what you can show. You can say you need help or have not tried yet.','请选择你能展示的内容。需要帮助或还没有尝试也可以。');showNotice(msg,'error');const el=$(i>=0?'reflection-question':id==='focus'?'reflection-focus':'reflection-evidence');el?.classList.add('missing');el?.setAttribute('aria-invalid','true');(el?.querySelector('input')||el)?.focus({preventScroll:true});el?.scrollIntoView({block:'center'});log('Reflection needs choice',m+': '+id);}
function next(){const m=R.mode(current());if(!m)return finishCard();const r=R.get(state),page=r.pages[m]||0;if(page<3){const id=R.topics[page].id;if(!state.teacher&&!R.valid(m,r[m][id]?.value))return reflectionError(id);reflectionPage(page+1);return;}const missing=state.teacher?[]:R.missing(state,m);if(missing.length)return reflectionError(missing[0]);finishCard();}
function finishCard(){sync();const c=current(),missing=M.missing(state,c);if(missing.length){const labels={answer:text('Choose an answer, then tap Check my thinking or Save my choice.','请选择答案，然后点击检查我的想法或保存选择。'),destination:text('Choose your destination.','请选择目的地。'),point:text('Select a map point using the map or a coordinate button.','请点击地图或坐标按钮选一个点。'),run:text('Tap Run to test the code on this card.','请点击运行，测试这张卡片上的代码。'),correction:text('Check the error hint and run again, or use I need teacher help.','请根据错误提示修正后再运行，或点击我需要老师帮助。'),change:text('Make the small code change described in YOUR TURN, then run again.','请按轮到你了的提示修改代码，然后再运行。'),line:text('Choose one code line to explain, or select I need help reading my code.','请选择一行代码进行解释，或选择我需要帮助读懂代码。')};showNotice(labels[missing[0]],'error');const selector={answer:'#question',destination:'.question',point:'.pointbar',run:'[data-action="run"]',correction:'#console',change:'#code',line:'#explain-line'}[missing[0]];const el=document.querySelector(selector);el?.classList.add('missing');el?.scrollIntoView({block:'center'});el?.querySelector('input,button,select')?.focus();log('Continue needs action',missing.join(', '));return;}
state.completed[c.id]={at:new Date().toISOString(),support:!!state.support[c.id]||!!state.answers[c.id]?.supported};state.unlocked=Math.max(state.unlocked,state.current+1);log('Completed card',state.completed[c.id].support?'with support':'attempt recorded');go(state.current+1);}
function insertCode(textValue){const box=$('code');if(!box)return;const w=work();w.undo=w.code;const start=box.selectionStart,end=box.selectionEnd;box.setRangeText(textValue,start,end,'end');w.code=box.value;highlight();box.focus();save();log('Inserted code helper',textValue);}
function setupCode(mapMode){return 'import turtle as t\nt.speed(0)\nt.pensize(4)\nt.color("blue")\n'+(mapMode?'t.penup()\nt.goto(0, -200)\nt.pendown()\n':'');}
function exportedCode(w,mapMode){return 'import turtle as t\n'+(mapMode?'screen = t.Screen()\nscreen.setup(width=800, height=600)\nscreen.bgpic("school_map.gif")\n':'')+'t.pensize(4)\nt.color("blue")\n'+(mapMode?'t.penup()\nt.goto(0, -200)\nt.pendown()\n':'')+'\n# My instructions\n'+w.code+'\n\nt.done()\n';}
function friendly(error,line){let en='Check the spelling, brackets and comma on this line.',zh='请检查这一行的拼写、括号和逗号。';if(/TimeLimit|time limit|too much time|timed out/i.test(error)){en='This program ran for too long. Stop and use fewer repetitions.';zh='程序运行时间过长。请停止，并减少重复次数。';}else if(/NameError|not defined/.test(error)){en='Check the name: Turtle commands start with t. Check capital letters too.';zh='请检查名称：Turtle 指令以 t. 开头，同时检查大小写。';}else if(/AttributeError/.test(error)){en='Check the command spelling. Try t.goto(x, y), t.penup() or t.pendown(). This editor supports a Turtle subset.';zh='请检查指令拼写。尝试 t.goto(x, y)、t.penup() 或 t.pendown()。本编辑器支持部分 Turtle 指令。';}return text((line?'Check line '+line+'. ':'')+en,(line?'请检查第 '+line+' 行。':'')+zh);}
function stop(record=true){if(runner){runner.terminate();runner=null;}if(frameListener){window.removeEventListener('message',frameListener);frameListener=null;}if(frame){frame.remove();frame=null;}clearTimeout(timeout);if(busy&&record&&current().workspace){const c=current(),w=work();w.ok=false;w.output=text('Stopped. Your code is safe. You can edit and run again.','已停止。代码仍然保留，可以修改后再次运行。');w.lastCode=w.code;state.runs.push({at:new Date().toISOString(),card:c.id,workspace:c.workspace,code:w.code,status:'stopped'});log('Stopped program');}busy=false;}
function run(){if(busy)return;sync();const c=current(),w=work();w.undo=w.code;const normal=L.normaliseCode(w.code);if(normal!==w.code){w.code=normal;log('Replaced full-width punctuation','Python-safe punctuation; code updated');notice=text('Replaced Chinese or curly punctuation with Python punctuation. Check the changed code.','已把中文或弯引号标点换为 Python 标点，请查看代码。');}else notice='';w.runs++;busy=true;render();const runCode=w.code,prefix=setupCode(!!c.map),offset=prefix.split('\n').length-1,code=prefix+runCode,cardId=c.id,workId=c.workspace;let delivered=false;
const finish=async r=>{if(delivered)return;delivered=true;stop(false);const line=r.line?Math.max(1,r.line-offset):null;w.ok=r.ok;w.lastCode=runCode;w.draws=r.draws||[];w.ranCards=Array.from(new Set([...w.ranCards,cardId]));w.output=(r.output||'')+(r.ok?text('Run finished. Compare the drawing with your prediction.','运行完成。请把图形与你的预测比较。'):friendly(r.error||'Unknown error',line));w.error=r.error||'';if(c.map)w.routeCheck=L.checkRoute(w.draws,state.destination);state.runs.push({at:new Date().toISOString(),card:cardId,workspace:workId,code:runCode,status:r.ok?'ran successfully':'error',error:r.error||'',line,routeCheck:w.routeCheck||null});log('Ran Python',r.ok?'success':w.error);render();const canvas=document.createElement('canvas');canvas.width=800;canvas.height=600;drawOn(canvas,w.draws,!!c.map,false,null,null);w.shot=canvas.toDataURL('image/jpeg',.83);await putShot(workId,{image:w.shot,code:runCode,at:new Date().toISOString(),ok:w.ok});delete w.shot;save(true);if(!r.ok){showNotice(w.output,'error');if(line&&$('code')){const lines=w.code.split('\n');const start=lines.slice(0,line-1).join('\n').length+(line>1?1:0);$('code').focus({preventScroll:true});$('code').setSelectionRange(start,start+(lines[line-1]||'').length);highlight();}}};
const fallback=()=>{runner?.terminate();runner=null;frame=document.createElement('iframe');frame.className='runtime-frame';frame.sandbox='allow-scripts';frame.title='Isolated Python execution';frame.src='runner-frame.html';document.body.appendChild(frame);frameListener=e=>{if(!frame||e.source!==frame.contentWindow)return;if(e.data?.type==='ready')frame.contentWindow.postMessage({type:'run',code},'*');if(e.data?.type==='result')finish(e.data);};window.addEventListener('message',frameListener);};
timeout=setTimeout(()=>finish({ok:false,error:'Program timed out. Stop and try fewer repetitions.',draws:[]}),5000);
try{if(location.protocol==='file:')fallback();else{runner=new Worker('runner-worker.js');runner.onmessage=e=>{if(e.data?.type==='result')finish(e.data);};runner.onerror=()=>fallback();runner.postMessage({code});}}catch{fallback();}}
function openHelp(title,html){$('help-title').textContent=title;$('help-content').innerHTML=html;$('help-dialog').showModal();log('Opened help',title);}
function deviceHelp(){openHelp(text('Device and saving help','设备与保存帮助'),`<p>${t('Tap a code line to edit. Use the punctuation buttons for brackets, a comma and a minus sign. Tap a map point, then Insert this point; you do not need to copy and paste.','点击代码行即可修改。用标点按钮输入括号、逗号和减号。点击地图上的点，再点击插入这个点，无需复制粘贴。')}</p><p>${t('On iPad: prepare the PDF first. Then tap Save / share PDF → Save to Files → Save. Open Teams and attach it from Files. A PDF preview is not a saved file.','iPad：先生成 PDF，再点击保存 / 分享 PDF → 存储到“文件” → 存储。然后打开 Teams，从“文件”附加。仅预览 PDF 不等于保存文件。')}</p><p>${t('Use the same browser and device to resume. Private browsing or clearing site data can remove saved work. If storage fails, download a backup before leaving.','继续学习时，请使用相同浏览器和设备。无痕浏览或清除网站数据可能删除记录。若存储失败，离开前请导出备份。')}</p>${state?B('Download backup','导出备份','backup')+B('Import my backup','导入我的备份','import-backup')+`<input type="file" id="backup-file" accept="application/json,.json" class="hidden">`:''}`);}
function download(file,name){const u=URL.createObjectURL(file),a=document.createElement('a');a.href=u;a.download=name||file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
async function backup(){sync();const shots={};for(const id of Object.keys(state.work))shots[id]=await getShot(id);download(new Blob([JSON.stringify({kind:'y7-w2-turtle-backup',state,shots,legacy})],{type:'application/json'}),M.filename(state,'_backup.json'));log('Requested backup download');}
function reflectionReviewNotice(){const gaps=['before','after'].filter(m=>R.missing(state,m).length);return !gaps.length?'':`<section class="notice"><strong>${t('A learning reflection still needs a choice.','学习反思中还有未选择的项目。')}</strong><p>${t('Your earlier work is safe. You can finish these short checks before exporting, or export an incomplete record if your teacher asks.','你之前的作品仍然保留。可以先完成简短检查再导出，或按老师要求导出未完成的记录。')}</p>${gaps.map(m=>B(m==='before'?'Finish Types of learning':'Finish Learning pitstop',m==='before'?'完成学习类型':'完成学习加油站','reflection-review:'+m)).join(' ')}</section>`;}
function submission(){const ipad=state.device==='ipad'||state.device==='auto'&&/iPad|iPhone|Macintosh/.test(navigator.userAgent)&&navigator.maxTouchPoints>1;return `${reflectionReviewNotice()}${legacy?`<div class="notice">${t('Earlier-version work was found and has not been changed. You can keep a copy.','找到了旧版本的学习记录，原记录未被更改。你可以保留一份副本。')}${B('Download earlier work','下载旧记录','legacy')}</div>`:''}<div class="download-actions">${B(reportVisible?'Hide report preview':'Review my report',reportVisible?'隐藏报告预览':'检查我的报告','review')}${B('Prepare my files','准备文件','prepare','primary',busy?'disabled':'')}</div>${reportVisible?'<div id="review-area" class="review-area">'+text('Preparing preview…','正在生成预览……')+'</div>':''}<div class="submission-grid"><section><h2>${t('1. Save your PDF','1. 保存 PDF')}</h2>${pdfFile?`<p>${esc(pdfFile.name)}</p><div class="download-actions">${B('Save / share PDF','保存 / 分享 PDF','share-pdf','primary')}${B('Download PDF','下载 PDF','download-pdf')}</div>`:`<p>${t('First tap Prepare my files above.','先点击上方的准备文件。')}</p>`}<label class="form-line">${t('Show instructions for','显示适用于以下设备的说明')}<select id="device"><option value="auto" ${state.device==='auto'?'selected':''}>${text('Automatic','自动')}</option><option value="ipad" ${state.device==='ipad'?'selected':''}>iPad / iPhone</option><option value="computer" ${state.device==='computer'?'selected':''}>Mac / Windows / Chromebook</option><option value="android" ${state.device==='android'?'selected':''}>Android</option></select></label><ol>${ipad?`<li>${t('Tap Save / share PDF. Choose Save to Files.','点击保存 / 分享 PDF，再选择存储到“文件”。')}</li><li>${t('Choose Downloads or another folder you recognise, then tap Save.','选择“下载”或你能找到的文件夹，再点击存储。')}</li><li>${t('If the PDF opens in Safari, use its Share button → Save to Files. Viewing alone does not save it.','如果 PDF 在 Safari 中打开，点击分享 → 存储到“文件”。仅查看不等于保存。')}</li>`:`<li>${t('Tap Download PDF. Find it in your browser downloads or Files / Downloads.','点击下载 PDF，在浏览器下载记录或“文件 / 下载”中找到它。')}</li><li>${t('If it opens instead, use Save / share PDF or the viewer’s download option.','如果文件直接打开，请使用保存 / 分享 PDF 或查看器中的下载选项。')}</li>`}</ol></section><section><h2>${t('2. Save your Python file','2. 保存 Python 文件')}</h2>${B('Save / share Python .py','保存 / 分享 Python 文件','share-python')}${B('Download Python .py','下载 Python 文件','download-python')}<p>${t('This is the program you wrote for your map route. Keep it with your PDF.','这是你为地图路线编写的程序，请与 PDF 一起保留。')}</p>${bundleFile?B('Download all files ZIP','下载完整文件包 ZIP','bundle'):''}<p class="entry-note">${t('The optional ZIP also contains the map GIF for running the program in desktop Python, plus any extension programs. You do not need desktop Python today.','可选 ZIP 文件包还包含地图 GIF 和拓展程序，供电脑上的 Python 使用。今天不需要使用电脑 Python。')}</p></section></div><section class="notice"><h2>${t('3. Turn in to Teams: Week 2 Practical','3. 提交到 Teams：Week 2 Practical')}</h2><ol><li>${t('Open your class → Assignments → Week 2 Practical.','打开你的班级 → 作业 → Week 2 Practical。')}</li><li>${t('Choose Add work / Attach and select your PDF and .py file from Files.','选择添加作业 / 附加，从“文件”选择 PDF 和 .py 文件。')}</li><li>${t('Wait for both files to appear. Tap Turn in and check the confirmation.','等待两个文件显示出来。点击提交，并检查确认状态。')}</li></ol>${[['saved','I found my saved PDF and Python file.','我已找到保存的 PDF 和 Python 文件。'],['turnedIn','I attached both files and tapped Turn in in Teams.','我已附加两个文件，并在 Teams 点击提交。']].map(([id,en,zh])=>`<label class="confirmed"><input type="checkbox" data-confirm="${id}" ${state.submission[id]?'checked':''}><span>${t(en,zh)}</span></label>`).join('')}<p class="entry-note">${t('These are your confirmations. This website cannot check Teams. You do not need to export again after ticking them.','这些是你的确认，本网站无法检查 Teams。勾选后不需要重新导出。')}</p></section><div class="session-actions">${B('Print-friendly report','打印版报告','print')}${B('Download backup','导出备份','backup')}${B('Reset my progress','重置我的进度','reset-progress','danger')}</div>`;}
async function prepare(){sync();busy=true;showNotice(text('Preparing the report and files. Please keep this page open.','正在准备报告和文件，请保持页面打开。'));document.querySelector('[data-action="prepare"]')?.setAttribute('disabled','');try{const html=await Report.html(state,getShot,legacy);pdfFile=await Report.pdf(html,M.filename(state,'.pdf'));const zip=new JSZip();zip.file(pdfFile.name,pdfFile);zip.file(M.filename(state,'_Route.py'),exportedCode(state.work.route||{code:''},true));const img=await new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('GET','assets/school_map.gif');x.responseType='arraybuffer';x.onload=()=>x.status===200||x.status===0?resolve(x.response):reject(new Error('Map file unavailable'));x.onerror=()=>reject(new Error('Map file unavailable'));x.send();}).catch(()=>null);if(img)zip.file('school_map.gif',img);for(const e of L.extensions)if(state.extensionAttempts.some(a=>a.id===e.id))zip.file(e.id+'.py',exportedCode(state.work[e.id]||{code:''},false));zip.file('README.txt','Submit the PDF and Route.py to Teams: Week 2 Practical.\nFor desktop Python, keep school_map.gif beside Route.py.\nThis is a practice map, not real navigation advice.');bundleFile=new File([await zip.generateAsync({type:'blob'})],M.filename(state,'_Files.zip'),{type:'application/zip'});log('Prepared PDF and files');busy=false;render();showNotice(text('Files are ready. Now save them on your device, then turn in to Teams.','文件已准备好。请先保存到设备，再提交到 Teams。'),'success');}catch(e){busy=false;render();showNotice(text('Could not prepare the PDF. Try again or use Print-friendly report. Your work is still here.','无法生成 PDF。请重试或使用打印版报告。学习记录仍然保留。')+' '+e.message,'error');}}
async function share(file){if(!file){showNotice(text('Tap Prepare my files first.','请先点击准备文件。'),'error');return;}try{if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Week 2 Practical'});log('Closed save/share window',file.name);showNotice(text('Check Files to confirm you saved it. Then attach it in Teams.','请在“文件”中确认已保存，再到 Teams 附加。'));}else{download(file);log('Requested download',file.name);showNotice(text('Download requested. If it opens as a preview, use Share → Save to Files.','已请求下载。如果打开的是预览，请点击分享 → 存储到“文件”。'));}}catch(e){showNotice(e.name==='AbortError'?text('Save cancelled. Your work is still here. You can try again.','保存已取消。学习记录仍保留，可以重试。'):text('Sharing is unavailable. Try Download or Device help.','暂时无法分享，请尝试下载或查看设备帮助。'));}}
function pythonFile(){return new File([exportedCode(state.work.route||{code:''},true)],M.filename(state,'_Route.py'),{type:'text/x-python'});}
// Reflection choices save immediately. There is no extra checkbox or keyword gate.
document.addEventListener('change',e=>{if(!state)return;const m=R.mode(current());if(!m)return;const r=R.get(state),v=e.target.value;let focus='';
 if(e.target.name==='reflection-choice'){const topic=R.topics[r.pages[m]||0];if(!topic||!R.valid(m,v))return;r[m][topic.id]={value:v,at:new Date().toISOString(),beforeAtAnswer:m==='after'?r.before[topic.id]?.value||null:null};log('Reflection choice',m+' · '+topic.id+' · '+R.label(m,v).en);focus='[data-reflection-choice="'+v+'"]';}
 else if(e.target.id==='reflection-focus'){r[m==='before'?'focus':'priority']=v;log('Reflection focus',m+' · '+v);focus='#reflection-focus';}
 else if(e.target.id==='reflection-evidence'){r.evidence=v;log('Reflection evidence',R.evidenceOptions.find(o=>o.id===v)?.label.en||'Not selected');focus='#reflection-evidence';}
 else return;notice='';save(true);render();document.querySelector(focus)?.focus({preventScroll:true});
});
document.addEventListener('input',e=>{if(state&&e.target.id==='reflection-note'){R.get(state).note=e.target.value;pdfFile=null;bundleFile=null;save();}});
document.addEventListener('focusout',e=>{if(state&&e.target.id==='reflection-note')log('Reflection note',e.target.value);});
document.addEventListener('click',async e=>{if(!state)return;if(e.target.closest('[data-action="reflection-work"]')){e.stopImmediatePropagation();const ids=['route','learn9',...Object.keys(state.work).reverse()],id=ids.find(id=>state.work[id]?.runs),w=state.work[id],shot=id?await getShot(id):null;openHelp(text('My work so far','我目前的作品'),w?`<p>${t('Point to one command or part of the drawing. Explain it, or show where you need help.','指着一条指令或图形的一部分，解释它，或指出需要帮助的地方。')}</p><pre class="example">${esc(w.code)}</pre>${shot?.image?`<img style="width:100%;height:auto" alt="Your latest captured Turtle drawing" src="${esc(shot.image)}">`:''}<p>${t('This is your latest saved work. Close this window to return to your check.','这是你最新保存的作品。关闭窗口即可返回检查。')}</p>`:t('No program has been run yet. Choose Not attempted yet if you have not tried this skill.','还没有运行过程序。如果尚未尝试这项技能，可以选择还没有尝试。'));return;}const p=e.target.closest('[data-reflection-page]'),b=e.target.closest('[data-action]'),m=R.mode(current());if(p&&m){e.stopImmediatePropagation();reflectionPage(Number(p.dataset.reflectionPage));}else if(b?.dataset.action==='back'&&m&&R.get(state).pages[m]>0){e.stopImmediatePropagation();reflectionPage(R.get(state).pages[m]-1);}else if(b?.dataset.action.startsWith('reflection-review:')){e.stopImmediatePropagation();const mode=b.dataset.action.split(':')[1],id=mode==='before'?'strategy':'reflect',index=L.cards.findIndex(c=>c.id===id);if(state.teacher||index<=state.unlocked){go(index);const missing=R.missing(state,mode);reflectionPage(Math.max(0,R.topics.findIndex(v=>v.id===missing[0])));}}});
document.addEventListener('submit',e=>{if(e.target.id!=='entry-form')return;e.preventDefault();const name=$('name').value.trim(),klass=$('klass').value.trim(),teacher=name.toLowerCase()==='teacher';if(!name||!teacher&&!klass){$('entry-error').textContent=text(!name?'Enter your name.':'Enter your class.','请输入'+(!name?'姓名。':'班级。'));$('entry-error').classList.remove('hidden');(!name?$('name'):$('klass')).focus();return;}device=$('entry-device').value;let saved=null;try{saved=JSON.parse(localStorage.getItem(M.key(name,klass)));legacy=JSON.parse(localStorage.getItem(teacher?'y7-t1-w2-practical-v2:teacher':'y7-t1-w2-practical-v2:'+klass.toLowerCase()+':'+name.toLowerCase()));}catch{}state=saved&&saved.version===1?saved:M.fresh(name,teacher?'':klass,lang,device);state.teacher=teacher;state.lang=lang;state.device=device;state.current=Math.min(state.current||0,L.cards.length-1);log(saved?'Resumed lesson':'Started lesson');render();});
document.addEventListener('input',e=>{if(e.target.id==='name'){$('klass').required=e.target.value.trim().toLowerCase()!=='teacher';$('klass').disabled=!$('klass').required;}if(e.target.id==='code'){const w=work();w.undo=w.code;w.code=e.target.value;pdfFile=null;bundleFile=null;highlight();save();}});
document.addEventListener('focusout',e=>{if(e.target.id==='code')log('Code draft',e.target.value);});
document.addEventListener('selectionchange',()=>{if(document.activeElement?.id==='code')highlight();});
document.addEventListener('scroll',e=>{if(e.target.id==='code')highlight();},true);
document.addEventListener('keydown',e=>{if(e.target.id==='code'){if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run();}if(e.key==='Tab'){e.preventDefault();insertCode('    ');}}});
document.addEventListener('change',e=>{const v=e.target.value;if(e.target.id==='language'){sync();lang=v;if(state){state.lang=lang;log('Language support',lang);render();}else{const n=$('name')?.value||'',c=$('klass')?.value||'';landing();$('name').value=n;$('klass').value=c;}}else if(e.target.id==='stage-select'){const i=Number(v);if(state.teacher||i<=state.unlocked)go(i);}else if(e.target.name==='answer'){const old=state.answers[current().id]||{};state.answers[current().id]={...old,value:Number(v),checked:false};log('Selected answer',current().question.choices[Number(v)].en);}else if(e.target.name==='destination'){state.destination=v;state.destinationChosen=true;log('Chose destination',v);}else if(e.target.id==='explain-line'){state.answers[current().id+'Line']=v;log('Selected command to explain',v);}else if(e.target.id==='next-action'){state.answers.nextAction=v;log('Next learning action',v);}else if(e.target.id==='device'){state.device=v;log('Device instructions',v);render();}else if(e.target.dataset.confirm){state.submission[e.target.dataset.confirm]=e.target.checked;log('Submission self-confirmation',e.target.dataset.confirm+': '+e.target.checked);save(true);}else if(e.target.id==='backup-file')importBackup(e.target.files[0]);});
async function importBackup(file){if(!file)return;if(file.size>15*1024*1024){alert(text('Choose a lesson backup smaller than 15 MB.','请选择小于 15 MB 的备份。'));return;}try{const data=JSON.parse(await file.text());if(data.kind!=='y7-w2-turtle-backup'||data.state?.version!==1||typeof data.state.name!=='string'||!data.state.work||!Array.isArray(data.state.runs))throw Error('Not a lesson backup');if(M.key(data.state.name,data.state.klass)!==M.key(state.name,state.klass))throw Error(text('Use your own name and class to open this backup.','请使用备份对应的姓名和班级登录。'));if(!confirm(text('Replace this lesson progress with your backup? A safety copy of current work will be downloaded first.','用备份替换本次学习进度？会先下载当前记录的安全副本。')))return;await backup();state=data.state;state.teacher=state.name.trim().toLowerCase()==='teacher';state.current=Math.max(0,Math.min(L.cards.length-1,Number(state.current)||0));state.lang=lang;legacy=data.legacy||legacy;for(const [id,shot] of Object.entries(data.shots||{}))if(shot?.image?.startsWith('data:image/'))await putShot(id,shot);$('help-dialog').close();render();showNotice(text('Your backup is restored.','备份已恢复。'),'success');}catch(e){alert(text('Could not open this backup: ','无法打开此备份：')+e.message);}}
document.addEventListener('click',async e=>{const point=e.target.closest('[data-point]'),ins=e.target.closest('[data-insert]'),word=e.target.closest('[data-word]');if(word){const v=L.terms[Number(word.dataset.word)];openHelp(v[0]+' · '+v[1],`<p>${esc(v[2])}</p><p lang="zh-Hans">${esc(v[3])}</p>`);return;}if(point){state.picked=point.dataset.point.split(',').map(Number);log('Selected map point',state.picked.join(', '));render();return;}if(ins){insertCode(ins.dataset.insert);return;}if(e.target.id==='drawing'&&current().map&&(current().pick||current().picker)){const r=e.target.getBoundingClientRect();state.picked=[Math.max(-400,Math.min(400,Math.round(((e.clientX-r.left)*800/r.width-400)/50)*50)),Math.max(-300,Math.min(300,Math.round((300-(e.clientY-r.top)*600/r.height)/50)*50))];log('Selected map point',state.picked.join(', '));render();return;}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='device-help')return deviceHelp();if(a==='words')return openHelp(text('Useful words','常用词语'),L.terms.map(v=>`<p><strong>${esc(v[0])} · ${esc(v[1])}</strong><br>${esc(v[2])}<br><span lang="zh-Hans">${esc(v[3])}</span></p>`).join(''));if(!state)return;
if(a==='next')next();else if(a==='back'){const rm=R.mode(current());if(rm&&R.get(state).pages[rm]>0){reflectionPage(R.get(state).pages[rm]-1);}else if(extension){extension=null;render();}else go(state.current-1);}else if(a==='check'){const c=current(),ans=state.answers[c.id];if(!ans||!Number.isInteger(ans.value)){showNotice(text('Choose one answer first.','请先选择一个答案。'),'error');$('question')?.classList.add('missing');return;}ans.checked=true;ans.supported=!c.choiceOnly&&ans.value!==c.question.correct;ans.attempts=ans.attempts||[];ans.attempts.push({at:new Date().toISOString(),value:ans.value,correct:c.choiceOnly?null:!ans.supported});log('Checked answer',c.question.choices[ans.value].en);render();}else if(a==='run')run();else if(a==='stop'){stop();render();}else if(a==='insert-point'){if(state.picked){const w=work();w.undo=w.code;w.code+=(w.code&&!w.code.endsWith('\n')?'\n':'')+'t.goto('+state.picked.join(', ')+')';log('Inserted selected point',state.picked.join(', '));render();$('code').focus();$('code').setSelectionRange(w.code.length,w.code.length);}}
else if(a==='undo'){const w=work();if(w.undo!==undefined){const now=w.code;w.code=w.undo;w.undo=now;log('Undo code edit');render();}}else if(a==='reset-code'){if(confirm(text('Reset only this code to its starter? Your other work stays safe.','只把这段代码恢复为初始代码？其他学习记录不会改变。'))){const w=work();w.undo=w.code;w.code=w.initial;w.draws=[];w.ok=false;w.lastCode=null;log('Reset workspace',current().workspace);render();}}
else if(a==='hint'){const c=current();openHelp(text('Try this next','试试下一步'),`<p>${both(c.hint||L.pair(c.map?'Follow the white corridor. Add a point at a corner before changing direction. Use x first, then y.':'Compare your line with t.goto(80, 0). Check the dot, brackets, comma and numbers.',c.map?'沿白色走廊前进。在改变方向之前，先在转角添加一个点。先写 x，再写 y。':'把代码与 t.goto(80, 0) 比较，检查点号、括号、逗号和数字。'))}</p><pre class="example">${esc(c.example||'t.goto(x, y)')}</pre><p>${t('Replace x and y with numbers from the grid.','把 x 和 y 换成网格上的数字。')}</p>`);}
else if(a==='support'){state.support[current().id]=true;log('Requested teacher help');showNotice(text('Your request is recorded. Raise your hand: the app does not notify your teacher. You can continue with support; your report will show this step needs help.','已记录求助。请举手：应用不会自动通知老师。你可以在帮助下继续，报告会标明这一步需要帮助。'));}
else if(a==='grid'){grid=!grid;log('Changed grid visibility',grid);render();}else if(a==='setup')openHelp(text('Prepared for you','已为你准备'),`<p>${t('This code is already run before your instructions. You only write the route commands.','这段代码已在你的指令之前运行。你只需要编写路线指令。')}</p><pre class="example">${esc(setupCode(true))}</pre>`);
else if(a.startsWith('extension:')){sync();extension=a.split(':')[1];state.extensionAttempts.push({id:extension,started:new Date().toISOString(),finished:null});log('Started extension',extension);notice='';render();}
else if(a==='extension-back'||a==='extension-finish'){sync();const att=[...state.extensionAttempts].reverse().find(x=>x.id===extension&&!x.finished);if(att){att.finished=new Date().toISOString();att.status=a==='extension-finish'?'student finished':'returned to choices';att.code=work()?.code||'';att.runs=work()?.runs||0;}log(a,extension);extension=null;render();}
else if(a==='review'){reportVisible=!reportVisible;render();if(reportVisible){$('review-area').innerHTML=await Report.html(state,getShot,legacy);log('Reviewed report');}}
else if(a==='prepare')prepare();else if(a==='share-pdf')share(pdfFile);else if(a==='download-pdf'){if(pdfFile){download(pdfFile);log('Requested PDF download',pdfFile.name);showNotice(text('Check that the PDF is saved in Files / Downloads. If it opens instead, use Share → Save to Files.','请在“文件 / 下载”确认 PDF 已保存。如果直接打开，请点击分享 → 存储到“文件”。'));}}
else if(a==='share-python')share(pythonFile());else if(a==='download-python'){const f=pythonFile();download(f);log('Requested Python download',f.name);}else if(a==='bundle'&&bundleFile){download(bundleFile);log('Requested submission ZIP');}else if(a==='backup')backup();else if(a==='import-backup')$('backup-file').click();else if(a==='legacy'){download(new Blob([JSON.stringify(legacy)],{type:'application/json'}),M.filename(state,'_Earlier_Work.json'));log('Requested earlier work backup');}
else if(a==='print'){const html=await Report.html(state,getShot,legacy);document.querySelector('.print-only')?.remove();const div=document.createElement('div');div.className='print-only';div.innerHTML=html;document.body.appendChild(div);log('Opened print fallback');window.print();}
else if(a==='reset-progress'){if(confirm(text('Reset only your progress in this redesigned lesson? Downloaded files and earlier-version work are kept. A backup will be downloaded first.','只重置你在本次新版课程中的进度？已下载文件和旧版本记录会保留，并先下载一份备份。'))){await backup();state=M.fresh(state.name,state.klass,lang,state.device);pdfFile=null;bundleFile=null;save(true);render();}}
else if(a==='change-student'){sync();save(true);stop();state=null;extension=null;pdfFile=null;bundleFile=null;legacy=null;landing();}
});
window.addEventListener('pagehide',()=>{sync();save(true);});
window.addEventListener('error',e=>{if(!state){$('app').innerHTML='<div class="unsupported"><h1>We could not open the lesson</h1><p>Please keep all lesson files together and reload. Ask your teacher if this continues.</p></div>';}else showNotice(text('Something could not finish. Your saved work has not been deleted. Use Device help to make a backup.','某个操作未能完成。已保存的学习记录未被删除，请使用设备帮助导出备份。'),'error');});
landing();
})();
